    "intro": "🎯 课前导读问题：Whose handbag is it?（这是谁的手袋？）\n📌 语法与句型重点：【一般疑问句 (Yes/No Question)】Be动词(Am/Is/Are) + 主语 + ...? — 用于询问某物是否属于某人，或询问某事是否属实。 例：Is this your handbag? (这是你的手提包吗？) ｜ 【指示代词 this/that 的用法】this/that + 名词 — this用于指代近处的人或事物，在询问物品归属时常用this。 例：Is this your handbag? (这是你的手提包吗？)\n💬 核心短语：“Excuse me”（用于引起他人注意、请求让路、或在打扰别人之前）；“Thank you very much”（表示非常感谢，语气较强）；“Pardon?”（用于没听清楚时礼貌地请求重复）",
