    "intro": "🎯 课前导读问题：Why can't Pamela type the letter?（帕梅拉为什么无法打信？）\n📌 语法与句型重点：【情态动词 can 的用法 (Can 的肯定句和否定句)】主语 + can/can not (can't) + 动词原形 — 表达能够做某事或不能做某事。 例：I can type this letter. (我能打这封信。) ｜ 【Can 引导的一般疑问句】Can + 主语 + 动词原形? — 询问某人是否有能力或许可做某事。 例：Can you come here a minute? (你能过来一下吗？)\n💬 核心短语：“Can you come here a minute please?”（礼貌请求某人过来一下）；“next door”（指隔壁的房间或地方）；“Can she type this letter for me?”（请求某人做某事）",
