    "intro": "🎯 课前导读问题：Does it ever snow in Greece?（希腊下过雪吗？）\n📌 语法与句型重点：【使用 It 表示天气】It's + 形容词 (hot, cold, warm, pleasant...) / It + 动词 (rains, snows, shines...) — 当描述天气状况时，使用 'it' 作为主语，而不是具体的事物如 'the sky' 或 'the weather'。。 例：It's very pleasant. (天气很宜人。) ｜ 【频率副词的使用】频率副词 + 形容词/动词 | 主语 + be + 频率副词 + 形容词 — always（总是）> often（经常）> sometimes（有时）> never（从不）。频率副词通常放在be动词之后、行为动词之前。。 例：It's always hot in July. (七月总是很热。)\n💬 核心短语：“come from”（表示来自某个地方，询问籍贯或出生地）；“What's the climate like?”（询问某个国家或地区的气候状况）；“What's the weather like?”（询问某个季节或时间的天气状况）",
