    "intro": "🎯 课前导读问题：Does the lady buy any chalk?（这位女士有没有买粉笔？）\n📌 语法与句型重点：【一般疑问句 (Yes/No Question) - 使用 Do/Does】Do/Does + 主语 + 动词原形 + ...? — 当主语是第一人称(I, we)、第二人称(you)或复数主语时用Do；当主语是第三人称单数(he, she, it)时用Does。 例：Do you have any writing paper? (你有信纸吗？) ｜ 【some和any的用法】some + 可数名词复数/不可数名词; any + 可数名词复数/不可数名词 — 在否定句和疑问句中用any，在肯定句中用some（表示请求或建议时也可用some）。 例：I want some envelopes. (我想要一些信封。)\n💬 核心短语：“Is that all?”（购物结束时常用语，询问是否还需要其他东西）；“What else do you want?”（询问对方还想要什么其他东西）；“Do you have any...?”（用于询问是否有某物）",
