    "intro": "🎯 课前导读问题：Why did the man need a phrasebook?（为什么这位男士需要一本常用语手册？）\n📌 语法与句型重点：【一般过去时 (Past Simple Tense)】主语 + 动词过去式 + 其他\n主语 + did not (didn't) + 动词原形 + 其他 — 用于叙述过去发生的事情，描述一系列按时间顺序发生的动作。 例：Last week Mrs. Mills went to London. (上周 Mills 夫人去了伦敦。) ｜ 【一般过去时的否定句和疑问句】否定句: 主语 + did not + 动词原形 + 其他\n一般疑问句: Did + 主语 + 动词原形 + 其他？ — 用于对过去发生的动作进行否定或提问。 例：He did not understand English. (他不懂英语。)\n💬 核心短语：“lose one's way”（迷路，指找不到要去的地方）；“ask someone the way”（向某人问路）；“Can you tell me the way to...?”（你能告诉我去...的路吗？用于礼貌地问路）",
