    "intro": "🎯 课前导读问题：What is Carol not going to buy?（卡罗尔不准备买什么？）\n📌 语法与句型重点：【Have got / Has got 表示拥有】主语 + have/has + got + 名词\n否定：主语 + haven't/hasn't + got + 名词\n疑问：Have/Has + 主语 + got + 名词？ — 用于描述某人拥有某物或在某处有某物。has got 用于第三人称单数（he/she/it）。。 例：We haven't got much tea or coffee. (我们的茶叶和咖啡不多了。) ｜ 【Some 和 Any 的用法】some + 可数名词复数/不可数名词\nany + 可数名词复数/不可数名词 — some 通常用于肯定句，any 用于否定句和疑问句。但在表示请求或希望得到肯定回答的疑问句中，也可用 some。。 例：We need some meat. (我们需要一些肉。)\n💬 核心短语：“go to the grocer's”（去杂货店买东西）；“make a shopping list”（列购物清单）；“have got / haven't got”（相当于have/has，表示拥有（英式英语常用））",
