    "intro": "🎯 课前导读问题：What does she mean by 'change' in the last sentence?（最后一名话中的“change\" 是什么意思？）\n📌 语法与句型重点：【过去进行时 (Past Continuous Tense)】主语 + was/were + 动词-ing — 用于描述过去正在进行的动作，为主要事件提供时间背景。 例：When my husband was going into the dining room this morning, he dropped some coins. (今天早上我丈夫走进餐厅时，把一些硬币掉在了地上。) ｜ 【过去完成时 (Past Perfect Tense)】主语 + had + 过去分词 — 用于描述在叙述的过去时间点之前已经完成的动作。 例：Tommy had already swallowed them before we could get the coins. (在我们能够拿到硬币之前，Tommy已经把硬币吞下去了。)\n💬 核心短语：“go into”（进入（某个地方））；“drop on the floor”（掉在地板上）；“look for”（寻找（强调动作过程））",
