    "intro": "🎯 课前导读问题：Does Susan have tea by herself?（苏珊是一个人喝茶吗？）\n📌 语法与句型重点：【must 与 have to 的用法区别】主语 + must/have to + 动词原形\n主语 + mustn't + 动词原形（表示禁止） — must多用于说话人认为必须做某事，have to多用于因外界条件或责任而必须做某事。在肯定句中两者可互换，但have to可用于更多时态。 例：I must water the garden first. (我必须先给花园浇水。（主观认为应该先做）) ｜ 【一般现在时第三人称单数 (means)】主语（he/she/it/名词单数）+ 动词第三人称单数形式 — 用于描述客观事实、普遍真理或习惯性动作。 例：It means you don't need to water the garden. (这意味着你不需要给花园浇水了。)\n💬 核心短语：“have tea”（喝茶/用茶点，表示喝茶的时间或活动）；“have to / must”（必须，不得不。must更强调主观意愿，have to更强调客观需要）；“look out of the window”（向窗外看）",
