    "intro": "🎯 课前导读问题：Who is only twenty-nine, and why is it so unclear?（谁只有29岁？为什么这件事如此含糊不清？）\n📌 语法与句型重点：【must be 表示肯定推测】主语 + must be + 形容词/名词 — 当说话人有把握确定某事时使用must be，表示非常肯定的推测。否定形式用can't be（不可能是）。。 例：It must be Karen Marsh. (那一定是凯伦·马什。) ｜ 【反义疑问句（附加疑问句）】陈述句 + 否定/肯定附加问句？ — 用于寻求确认或同意，语调不同表示的意义不同：升调表示询问，降调表示强调。。 例：Doesn't Karen Marsh look old! (凯伦·马什看起来不是很老吗！)\n💬 核心短语：“Can you recognize...?”（用于询问对方是否能认出某人或某物）；“It must be...”（表示有把握的推测，意为一定是）；“It can't be...”（表示否定的推测，意为不可能是）",
