    "intro": "🎯 课前导读问题：What's the problem about deciding on a holiday?（决定如何度假有什么为难的地方？）\n📌 语法与句型重点：【may/might 表示可能性】主语 + may/might + 动词原形 — 用于谈论可能发生但不确定的事情，表达'也许、可能'的意思。may更肯定一些，might更委婉、不确定。。 例：We may go abroad this year. (我们今年可能出国。) ｜ 【be going to 表示计划或意图】主语 + am/is/are going to + 动词原形 — 用于表达已经决定要做的事情，有明确的计划意图。疑问句形式'Where are you going to...?'用来询问对方的计划。。 例：Where are you going to spend your holidays? (你打算去哪里度假？)\n💬 核心短语：“go abroad”（表示出国、去国外）；“make up one's mind”（表示下定决心、做决定）；“travel by sea/air”（表示乘船/飞机旅行）",
