    "intro": "🎯 课前导读问题：What would Julie like to do, if she had the money?（如果朱莉有那笔钱，她想做什么呢？）\n📌 语法与句型重点：【第二条件句 (Second Conditional)】If + 主语 + 过去式（be动词用were）, 主语 + would/could/might + 动词原形 — 表示与事实相反或不太可能实现的假设，常用于表达梦想或不太可能发生的事情。 例：If I win a lot of money, I'll buy you a mink coat. (如果我赢了很多钱，我会给你买一件貂皮大衣。) ｜ 【If引导的疑问句 (If Clause Questions)】What will you do if + 主语 + 动词过去式? — 用于询问对方在某种假设情况下会采取什么行动。 例：What will you do if you win a lot of money? (如果你赢了很多钱，你会做什么？)\n💬 核心短语：“do the football pools”（指参与足球博彩投注）；“win something”（赢得某物；在比赛中获得奖品或奖金）；“buy someone something”（给某人买某物）",
